"""Build TP-local packed MXFP4 MoE inputs from real C16 tensor statistics."""
from __future__ import annotations
from functools import lru_cache
import hashlib
import math
from typing import Any
import torch
CALIBRATION_SHA256 = '2b9a3aa0d40ce99778025263e99a33a3bc513433aad5a0b18336bde56c4ffd54'
EXPERTS = 512
HIDDEN = 2560
INTERMEDIATE = 320
TOP_K = 10
W13_NIBBLES = (0.11150503, 0.10465813, 0.08902216, 0.07053, 0.0724926, 0.053594, 0.038312, 0.015433, 0.0, 0.10487747, 0.08911133, 0.070606, 0.072417, 0.053832, 0.038225, 0.015383)
W2_NIBBLES = (0.09921122, 0.09503698, 0.08414125, 0.070284, 0.07659435, 0.060911, 0.045258, 0.017971, 0.0, 0.09500074, 0.08462095, 0.070069, 0.076484, 0.060987, 0.045335, 0.018095)
W13_SCALES = ((118, 5.15e-05), (119, 0.26831818), (120, 0.70930767), (121, 0.02197742), (122, 0.00032902), (123, 1.621e-05))
W2_SCALES = ((118, 0.00135899), (119, 0.45011711), (120, 0.53942585), (121, 0.00843525), (122, 0.00052261), (123, 0.00012398), (124, 1.621e-05))

def _lookup(values: tuple[tuple[int, float], ...], device: str, buckets: int=65536) -> torch.Tensor:
    counts = [round(probability * buckets) for (_, probability) in values]
    difference = buckets - sum(counts)
    largest = max(range(len(counts)), key=lambda index: values[index][1])
    counts[largest] += difference
    table = [code for ((code, _), count) in zip(values, counts) for _ in range(count)]
    if len(table) != buckets:
        raise ValueError('MXFP4 calibration lookup did not cover all probability buckets')
    return torch.tensor(table, dtype=torch.uint8, device=device)

def _nibble_lookup(probabilities: tuple[float, ...], device: str) -> torch.Tensor:
    if len(probabilities) != 16:
        raise ValueError('MXFP4 nibble calibration is incomplete')
    return _lookup(tuple(((index, value) for (index, value) in enumerate(probabilities))), device, buckets=256)

def _packed(shape: tuple[int, ...], stride: tuple[int, ...], lookup: torch.Tensor, *, nibble: bool, generator: torch.Generator, device: str) -> torch.Tensor:
    elements = 1
    for size in shape:
        elements *= size
    flat = torch.empty((elements,), dtype=torch.uint8, device=device)
    for begin in range(0, elements, 1 << 25):
        end = min(elements, begin + (1 << 25))
        random_bits = torch.randint(0, 65536, (end - begin,), generator=generator, dtype=torch.int32, device=device)
        low = lookup[(random_bits & 255 if nibble else random_bits).long()]
        if nibble:
            high = lookup[(random_bits >> 8).long()]
            flat[begin:end] = low | high << 4
        else:
            flat[begin:end] = low
    return torch.as_strided(flat, shape, stride)

@lru_cache(maxsize=2)
def _model_parameters(device: str) -> tuple[torch.Tensor, ...]:
    generator = torch.Generator(device=device).manual_seed(383803)
    w13 = _packed((EXPERTS, 1280, 640), (819200, 1, 1280), _nibble_lookup(W13_NIBBLES, device), nibble=True, generator=generator, device=device)
    w13_scale = _packed((EXPERTS, 80, 640), (51200, 1, 80), _lookup(W13_SCALES, device), nibble=False, generator=generator, device=device)
    w2 = _packed((EXPERTS, 160, HIDDEN), (409600, 1, 160), _nibble_lookup(W2_NIBBLES, device), nibble=True, generator=generator, device=device)
    w2_scale = _packed((EXPERTS, 10, HIDDEN), (25600, 1, 10), _lookup(W2_SCALES, device), nibble=False, generator=generator, device=device)
    return (w13, w13_scale, torch.zeros((EXPERTS, 640), dtype=torch.float32, device=device), w2, w2_scale, torch.zeros((EXPERTS, HIDDEN), dtype=torch.float32, device=device))

def _make_inputs(tokens: int, dtype: str='bfloat16', device: str='cuda', routing_mix: float | None=None, seed: int | None=None) -> dict[str, object]:
    if type(tokens) is not int or not 1 <= tokens <= 8192:
        raise ValueError('MoE token count is outside the observed C16 range')
    if dtype != 'bfloat16':
        raise ValueError('MoE activation dtype differs from the observed ABI')
    seed = (torch.initial_seed() % (2**63)) if seed is None else seed
    (profile, moments) = _profile_for_tokens(tokens, seed, routing_mix)
    generator = torch.Generator(device=device).manual_seed(seed)
    normal = torch.randn((tokens, HIDDEN), generator=generator, device=device, dtype=torch.float32)
    chi = torch.zeros_like(normal)
    for _ in range(5):
        chi.add_(torch.randn(normal.shape, generator=generator, device=device, dtype=torch.float32).square())
    x = (normal * (3.0 / chi.clamp_min(1e-12)).sqrt() * moments['std'] + moments['mean']).clamp(moments['min'], moments['max'])
    logits = make_router_logits_from_load(tokens, profile, seed, device)
    (w13, w13_scale, w13_bias, w2, w2_scale, w2_bias) = _model_parameters(device)
    return {'x': x.to(torch.bfloat16), 'router_logits': logits.to(torch.float32), 'w13_weight_packed': w13, 'w13_scale_packed': w13_scale, 'w13_bias': w13_bias, 'w2_weight_packed': w2, 'w2_scale_packed': w2_scale, 'w2_bias': w2_bias, 'global_num_experts': EXPERTS, 'top_k': TOP_K, 'activation': 'silu'}

def make_router_logits_from_load(tokens: int, profile: dict[str, Any], seed: int, device: str='cpu') -> torch.Tensor:
    """Fit routing work directly, keeping selected-score covariance separate.

    Expert identity proposals follow observed inclusion counts. Only aggregate
    moments/counts are used; no original rows or tensor payloads are embedded.
    CPU construction avoids one GPU synchronization per repaired token row.
    """
    if type(tokens) is not int or not 1 <= tokens <= 8192:
        raise ValueError('invalid observed token count')
    if type(seed) is not int or not 0 <= seed < 2 ** 63:
        raise ValueError('invalid random seed')
    phases = profile['phases']
    if len(phases) not in (1, 4):
        raise ValueError('invalid phase count')
    generator = torch.Generator().manual_seed(seed)
    probabilities = torch.tensor([phase['inclusion_probability'] for phase in phases], dtype=torch.float32, device='cpu')
    means = torch.tensor([phase['outside_mean'] for phase in phases], dtype=torch.float32, device='cpu')
    deviations = torch.tensor([phase['outside_std'] for phase in phases], dtype=torch.float32, device='cpu')
    if probabilities.shape != (len(phases), 512) or means.shape != probabilities.shape or deviations.shape != probabilities.shape:
        raise ValueError('invalid expert table geometry')
    if not bool(torch.isfinite(probabilities).all() and torch.isfinite(means).all() and torch.isfinite(deviations).all()):
        raise ValueError('nonfinite calibration')
    if bool((probabilities <= 0).any() or (probabilities >= 1).any() or (deviations < 0).any()):
        raise ValueError('invalid probability or standard deviation')
    phase_ids = torch.arange(tokens, device='cpu') % len(phases)
    proposal_weight = -torch.log1p(-probabilities[phase_ids])
    uniform = torch.rand((tokens, 512), generator=generator, dtype=torch.float32, device='cpu').clamp_(1e-07, 1 - 1e-07)
    proposal_score = proposal_weight.log() - (-uniform.log()).log()
    proposals = proposal_score.topk(20, dim=-1).indices.tolist()
    overlap = float(profile['small_batch_overlap_limit']) if tokens <= 4 else 1.0
    limit = float(profile['small_batch_max_inclusion'])
    if not math.isfinite(limit) or not 0 < limit <= 1:
        raise ValueError('invalid small-batch inclusion limit')
    max_uses = math.ceil(tokens * limit) if tokens <= 4 else tokens
    if not math.isfinite(overlap) or not 0 <= overlap <= 1:
        raise ValueError('invalid overlap statistic')
    selected = []
    use_counts = [0] * 512
    previous: set[int] = set()
    for (index, candidates) in enumerate(proposals):
        allowed = math.floor(index * overlap * 10) - math.floor((index - 1) * overlap * 10) if index else 10
        row: list[int] = []
        shared = 0
        for expert in candidates:
            if use_counts[expert] >= max_uses:
                continue
            if expert in previous:
                if shared >= allowed:
                    continue
                shared += 1
            row.append(expert)
            if len(row) == 10:
                break
        if len(row) != 10:
            raise ValueError('routing repair failed to produce ten distinct experts')
        selected.append(row)
        for expert in row:
            use_counts[expert] += 1
        previous = set(row)
    ids = torch.tensor(selected, dtype=torch.int64, device='cpu')
    score_mean = torch.tensor(profile['selected_score_mean'], dtype=torch.float32, device='cpu')
    score_factor = torch.tensor(profile['selected_score_factor'], dtype=torch.float32, device='cpu')
    if score_mean.shape != (10,) or score_factor.shape != (10, 10):
        raise ValueError('invalid selected score geometry')
    if not bool(torch.isfinite(score_mean).all() and torch.isfinite(score_factor).all()):
        raise ValueError('nonfinite selected score calibration')
    if 'score_quantiles' in profile:
        probabilities = torch.tensor(profile['quantile_probabilities'], dtype=torch.float64, device='cpu')
        quantiles = torch.tensor(profile['score_quantiles'], dtype=torch.float64, device='cpu')
        factor = torch.tensor(profile['score_copula_factor'], dtype=torch.float64, device='cpu')
        if probabilities.ndim != 1 or quantiles.shape != (len(probabilities), 11) or factor.shape != (11, 11):
            raise ValueError('invalid score copula geometry')
        if not bool(torch.isfinite(probabilities).all() and torch.isfinite(quantiles).all() and torch.isfinite(factor).all()):
            raise ValueError('nonfinite score copula')
        if not torch.allclose(factor.square().sum(-1), torch.ones(11, dtype=torch.float64, device='cpu'), atol=1e-05, rtol=1e-05):
            raise ValueError('score copula latent variables must have unit variance')
        if probabilities[0] != 0 or probabilities[-1] != 1 or (not bool((probabilities.diff() > 0).all())) or (not bool((quantiles.diff(dim=0) >= 0).all())):
            raise ValueError('invalid score quantile ordering')
        latent = torch.randn((tokens, 11), generator=generator, dtype=torch.float64, device='cpu') @ factor.T
        uniform = ((latent / math.sqrt(2)).erf() + 1) * 0.5
        columns = torch.arange(11, device='cpu').expand(tokens, -1)
        lo = torch.searchsorted(probabilities, uniform.contiguous(), right=True).sub(1).clamp(0, len(probabilities) - 2)
        fraction = (uniform - probabilities[lo]) / (probabilities[lo + 1] - probabilities[lo])
        sampled = quantiles[lo, columns] * (1 - fraction) + quantiles[lo + 1, columns] * fraction
        weights = sampled[:, :10].sort(dim=-1, descending=True).values
        if not bool((weights > 0).all()):
            raise ValueError('nonpositive fitted routing weight')
        weights = weights / weights.sum(dim=-1, keepdim=True)
        scores = (weights.log() + sampled[:, 10:]).float()
    else:
        score_noise = torch.randn((tokens, 10), generator=generator, dtype=torch.float32, device='cpu')
        scores = (score_noise @ score_factor.T + score_mean).sort(dim=-1, descending=True).values
    bottom = scores[:, -1:]
    strict_cap = torch.nextafter(bottom, torch.full_like(bottom, float('-inf')))
    means = means[phase_ids].double()
    deviations = deviations[phase_ids].double().clamp_min(1e-12)
    cap = strict_cap.double()
    cumulative_cap = 0.5 * torch.erfc((means - cap) / (deviations * math.sqrt(2)))
    outside_mask = torch.ones((tokens, 512), dtype=torch.bool, device='cpu')
    outside_mask.scatter_(1, ids, False)
    tail_mask = (cumulative_cap < 1e-285) & outside_mask
    uniform = torch.rand((tokens, 512), generator=generator, dtype=torch.float64, device='cpu').clamp_min(1e-15)
    probability = (uniform * cumulative_cap).clamp(1e-300, 1 - 1e-15)
    standardized = torch.special.ndtri(probability)
    outside = means + deviations * standardized
    if bool(tail_mask.any()):
        boundary = ((means - cap) / deviations)[tail_mask]
        rate = 0.5 * (boundary + torch.sqrt(boundary.square() + 4))
        tail_values = torch.empty_like(boundary)
        pending = torch.ones_like(boundary, dtype=torch.bool)
        for _ in range(64):
            if not bool(pending.any()):
                break
            current_rate = rate[pending]
            proposal = boundary[pending] - torch.rand(current_rate.shape, generator=generator, dtype=torch.float64, device='cpu').clamp_min(1e-15).log() / current_rate
            accepted = torch.rand(current_rate.shape, generator=generator, dtype=torch.float64, device='cpu').clamp_min(1e-15).log() <= -0.5 * (proposal - current_rate).square()
            positions = pending.nonzero(as_tuple=True)[0][accepted]
            tail_values[positions] = proposal[accepted]
            pending[positions] = False
        if bool(pending.any()):
            raise ValueError('truncated Gaussian tail sampling exceeded retry budget')
        outside[tail_mask] = means[tail_mask] - deviations[tail_mask] * tail_values
    result = outside.float().minimum(strict_cap)
    result.scatter_(1, ids, scores)
    if not bool(torch.isfinite(result).all()):
        raise ValueError('generated nonfinite logits')
    permutation = torch.randperm(512, generator=generator, device='cpu')
    return result[:, permutation].contiguous().to(device=device)

def _moment_model(rows):
    mean = sum((row['mean'] for row in rows)) / len(rows)
    variance = sum((row['std'] ** 2 + (row['mean'] - mean) ** 2 for row in rows)) / len(rows)
    return {'mean': mean, 'std': variance ** 0.5, 'min': min((row['quantiles']['min'] for row in rows)), 'max': max((row['quantiles']['max'] for row in rows))}

def _blend_routing_profiles(a,b,alpha):
    result=dict(a);result['phases']=[]
    for i,p in enumerate(a['phases']):
        other=b['phases'][i%len(b['phases'])];phase={}
        for key in ('inclusion_probability','outside_mean','outside_std'):
            first=torch.tensor(p[key],dtype=torch.float64,device='cpu');second=torch.tensor(other[key],dtype=torch.float64,device='cpu')
            if key in ('outside_mean','outside_std'):
                unreliable=torch.tensor(other['outside_std'],dtype=torch.float64,device='cpu')<.05;second=torch.where(unreliable,first,second)
            phase[key]=((1-alpha)*first+alpha*second).tolist()
        result['phases'].append(phase)
    first=torch.tensor(a['score_quantiles'],dtype=torch.float64,device='cpu');second=torch.tensor(b['score_quantiles'],dtype=torch.float64,device='cpu')
    quantiles=(1-alpha)*first+alpha*second;quantiles[0]=torch.minimum(first[0],second[0]);quantiles[-1]=torch.maximum(first[-1],second[-1]);result['score_quantiles']=quantiles.tolist()
    x=torch.tensor(a['score_copula_factor'],dtype=torch.float64,device='cpu');y=torch.tensor(b['score_copula_factor'],dtype=torch.float64,device='cpu');cov=(1-alpha)*(x@x.T)+alpha*(y@y.T);values,vectors=torch.linalg.eigh(cov);factor=vectors@torch.diag(values.clamp_min(1e-8).sqrt());factor/=factor.square().sum(-1,keepdim=True).sqrt();result['score_copula_factor']=factor.tolist()
    return result

def _profile_for_tokens(tokens, seed, routing_mix):
    if tokens <= 64:
        key = 'decode_small' if tokens <= 4 else 'mtp_decode'
        if tokens>4:
            alpha=.5 if routing_mix is None else float(routing_mix)
            if not math.isfinite(alpha) or not 0<=alpha<=1:raise ValueError('routing_mix must be in [0,1]')
            return (_blend_routing_profiles(ROUTER_PROFILES[key],ROUTER_PROFILES['mtp_decode_wide'],alpha),_moment_model(ACTIVATION_STATISTICS[key]))
        return (ROUTER_PROFILES[key], _moment_model(ACTIVATION_STATISTICS[key]))
    alpha = int.from_bytes(hashlib.sha256(str(seed).encode()).digest()[:8], 'big') / (2 ** 64 - 1) if routing_mix is None else float(routing_mix)
    if not math.isfinite(alpha) or not 0 <= alpha <= 1:
        raise ValueError('routing_mix must be finite and between zero and one')
    (broad, hot) = (ROUTER_PROFILES['prefill_initial'], ROUTER_PROFILES['prefill_prior_context'])
    phase = {}
    for key in ('inclusion_probability', 'outside_mean', 'outside_std'):
        (a, b) = (torch.tensor(broad['phases'][0][key], dtype=torch.float32, device='cpu'), torch.tensor(hot['phases'][0][key], dtype=torch.float32, device='cpu'))
        phase[key] = ((1 - alpha) * a + alpha * b).tolist()
    (a, b) = (torch.tensor(broad['selected_score_factor'], dtype=torch.float32, device='cpu'), torch.tensor(hot['selected_score_factor'], dtype=torch.float32, device='cpu'))
    cov = (1 - alpha) * (a @ a.T) + alpha * (b @ b.T)
    (vals, vecs) = torch.linalg.eigh(cov)
    factor = vecs @ torch.diag(vals.clamp_min(1e-08).sqrt())
    score_mean = [(1 - alpha) * a + alpha * b for (a, b) in zip(broad['selected_score_mean'], hot['selected_score_mean'])]
    profile = {'phases': [phase], 'selected_score_mean': score_mean, 'selected_score_factor': factor.tolist(), 'small_batch_overlap_limit': broad['small_batch_overlap_limit'], 'small_batch_max_inclusion': broad['small_batch_max_inclusion']}
    (a, b) = (_moment_model(ACTIVATION_STATISTICS['prefill_initial']), _moment_model(ACTIVATION_STATISTICS['prefill_prior_context']))
    moments = {key: (1 - alpha) * a[key] + alpha * b[key] for key in ('mean', 'std', 'min', 'max')}
    profile['quantile_probabilities'] = broad['quantile_probabilities']
    profile['score_quantiles'] = ((1 - alpha) * torch.tensor(broad['score_quantiles'], dtype=torch.float64, device='cpu') + alpha * torch.tensor(hot['score_quantiles'], dtype=torch.float64, device='cpu')).tolist()
    ba = torch.tensor(broad['score_copula_factor'], dtype=torch.float64, device='cpu')
    ha = torch.tensor(hot['score_copula_factor'], dtype=torch.float64, device='cpu')
    correlation = (1 - alpha) * (ba @ ba.T) + alpha * (ha @ ha.T)
    (vals, vecs) = torch.linalg.eigh(correlation)
    factor = vecs @ torch.diag(vals.clamp_min(1e-10).sqrt())
    factor = factor / factor.square().sum(-1, keepdim=True).sqrt()
    profile['score_copula_factor'] = factor.tolist()
    return (profile, moments)
